parameters.jsCode:
// ССЫЛКА НА ЮНИТ: ПУТЬ ТОЧНЫЙ, ХОСТ — ЛЮБОЙ НАШ.
//
// Заказчик часто присылает не название подразделения, а ссылку:
//   …tbank.ru/structure/resource/units/<uuid>   — управленческая структура
//   …tbank.ru/product-catalog/product/<uuid>    — Каталог продуктов
// В ссылке стоит `id` юнита, а в основных витринах его НЕТ — там только `rk`.
// Перевод делается через справочник (dds.management_unit / dds.functional_unit),
// и без него ссылка бесполезна.
//
// ХОСТ БЫЛ ЗАШИТ КАК `my.tbank.ru` — И ЭТО СТОИЛО ЖИВОГО ПРОГОНА 03.09.
// Тот же интерфейс структуры отдаётся и с `hr.tbank.ru`; заказчик прислал
// ссылку оттуда, признак не сработал, справочник не запрашивался, и бот
// пять раз подряд просил назвать команду словами — при том что название
// стояло в тексте ссылки с первого сообщения. Одиннадцать минут и девять
// прогонов ушли на то, что код умеет за полторы секунды.
//
// Отсюда правило: узнаём по ПУТИ, а хост принимаем любой в `tbank.ru`.
// Путь `structure/resource/units/<uuid>` ни на что другое не похож, а список
// поддоменов заранее не известен — в выгрузках канала их уже три.
// Точность при этом не теряется: ложных срабатываний у такого пути нет,
// поэтому по нему добирается не только рецепт, но и инвентарь обоих
// справочников — имена полей `*_unit_id` и `*_unit_rk` автор иначе
// не увидит и подставит правдоподобные.
//
// Живой прогон 2026-08-31 (тот же класс): бот искал uuid из ссылки среди
// значений mapped_management_unit_nm и lvl5_mapped_management_unit_rk,
// не нашёл — и написал заказчику, что юнит «не обнаружился ни по названию,
// ни по идентификатору». Ни в одном из этих полей его и не могло быть.
const UNIT_LINK_RE =
  /[a-z0-9.-]*\btbank\.ru\/(structure\/resource\/units|product-catalog\/product)\/([0-9a-f-]{8,})/i;

// Нормализация события Time и решение, обращение это или нет.
//
// Форма события зависит от версии ноды и типа события: пост приходит либо
// объектом на верхнем уровне, либо JSON-СТРОКОЙ в data.post. Без распаковки
// все поля читаются как undefined, а условия вида `x ?? '' === ''` при этом
// не падают, а ПРОХОДЯТ — фильтр молча пропускает всё.
const PREFIXES     = ["Cross Data |"];
const REQUIRE_ROOT = true;
// Логин бота: по нему распознаётся @упоминание. Пусто — путь по тегу выключен.
const MENTION      = ["bully", "Булли"];  // список имён, на которые бот отзывается
// Личка: ответ в треде бота — продолжение разговора, тег там не нужен,
// потому что в диалоге, кроме двоих, никого нет. В канале иначе: там тред
// живёт своей жизнью — дежурный, согласование, обсуждение, — и бот, отвечающий
// на всё подряд, стал бы шумом. Отсюда разные значения флага, а не одно.
const ALLOW_THREAD = false;
const DROP_BOT     = false;
const REQUIRE_DM   = false;
const ALLOWLIST    = [];

const asObj = (v) => {
  if (!v) return {};
  if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return {}; } }
  return v;
};

const src  = $json || {};
const data = asObj(src.data ?? {});
const post = asObj(src.post ?? data.post ?? {});

const message = String(post.message ?? '');
const rootId  = String(post.root_id ?? '');
const postId  = String(post.id ?? '');

// Реплика в треде. Mattermost у КОРНЕВОГО поста иногда проставляет root_id
// равным его же id — это всё ещё корень, а не ответ.
const isReply = Boolean(rootId && rootId !== postId);

// УПОМИНАНИЕ БОТА. Имён несколько: логин латиницей и то, как его зовут люди
// («@Булли»). Кириллица в username Mattermost запрещена, поэтому одно
// значение здесь означало бы выбрать, какое написание работает.
//
// Ограничитель — «дальше не буква и не цифра», и БУКВА ЛЮБОГО АЛФАВИТА.
// `\b` не годится: он совпал бы и с `@bully_bot`, то есть бот отзывался бы
// на чужое имя, начинающееся так же. Но и класс `[a-z0-9_.\-]` не годится:
// он латинский, и на имени «Булли» пропускал `@Буллика` и `@Буллиан` —
// тот же капкан, что `\b` по кириллице, только вывернутый наизнанку.
// `\p{L}` с флагом `u` закрывает оба алфавита разом.
const mentioned = MENTION.some((name) => {
  const n = String(name || '').trim();
  if (!n) return false;
  return new RegExp('@' + n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') +
                    '(?![\\p{L}\\p{N}_.\\-])', 'iu').test(message);
});

// ПРОДОЛЖЕНИЕ РАЗГОВОРА, а не новое обращение. Бот задаёт уточняющие вопросы
// («какая нужна гранулярность?»), и до этой правки ответ на них не читался
// вовсе: реплика в треде отсеивалась как «не обращение», а человек ждал.
// Для такого поста нужен ВЕСЬ тред: без него ответ «по дням» не значит ничего.
const isFollowUp = mentioned || (ALLOW_THREAD && isReply);
// Корень треда для догоняющего чтения. У реплики это root_id, у корневого
// поста — он сам: тегнуть бота могут и под первым сообщением.
const threadRoot = isReply ? rootId : postId;

// Первая строка без markdown-обвязки: intake-воркфлоу может выделять тему
// жирным, и тогда сообщение начинается со звёздочек, а не с «Cross Data».
const head = message.split('\n')[0].replace(/^[\s>*_#`~]+/, '').trim();
const topic = PREFIXES.find(
  (p) => head.toLowerCase().startsWith(String(p).toLowerCase())
) || '';

// -------------------------------------------------- разбор intake-формы
//
// Обращение приходит не текстом, а заполненной формой:
//
//   Cross Data | Вопрос по отчетам от пользователя @Anna Sokolova
//   Выбери домен:
//   Стоимость и расходы на персонал
//   Укажи ссылку на отчет:
//   https://proteus.tcsbank.ru/superset/dashboard/…
//   Напиши свой вопрос:
//   привет! подскажите, долились ли бюджеты…
//
// Три из этих полей — самые надёжные сигналы, какие вообще есть: их проставил
// человек, а не вывела модель. Домен глазами заказчика и ссылка на отчёт
// позволяют КОДОМ увидеть и промах роутера, и пробел базы, не платя за это
// вторым вызовом модели.
//
// Разбор общий, а не по списку известных полей: у каждой темы формы свои поля
// (у выгрузки — бизнес-задача, состав данных, чувствительность), и список
// разъедется молча при первой правке формы. Поэтому метка — это короткая
// строка, кончающаяся двоеточием, а её значение — всё до следующей метки.
const LABEL_RE = /^[^\n]{0,60}:$/;

const sections = [];              // [{ label, value }] в порядке появления
{
  let label = '';
  let buf = [];
  const flush = () => {
    if (label) sections.push({ label, value: buf.join('\n').trim() });
    buf = [];
  };
  // Шапку пропускаем: тема и автор разбираются отдельно ниже.
  for (const raw of message.split('\n').slice(1)) {
    const l = raw.replace(/^[\s>*_#`~]+/, '').replace(/[\s*_`~]+$/, '').trim();
    if (l && LABEL_RE.test(l)) { flush(); label = l.slice(0, -1).trim(); continue; }
    buf.push(raw);
  }
  flush();
}

const section = (re) => (sections.find((s) => re.test(s.label)) || {}).value || '';

// Тема без префикса и без хвоста «от пользователя @X». В телеметрии тема
// берётся из префикса целиком (kind), здесь нужна человекочитаемая часть:
// она печатается шапкой в канале джуна вместо цитаты обращения.
const afterPrefix = topic ? head.slice(topic.length).trim() : head;
// Хвост «от пользователя @X» отрезается. Без \b намеренно: в JS границы слова
// определены по ASCII, и \bот перед кириллической «о» не совпадает НИКОГДА —
// проверка была зелёной по подстроке и молча не работала.
const authorAt = afterPrefix.search(/(?:^|[\s(,·|])от\s+пользовател/i);
// ТЕМА ЕСТЬ ТОЛЬКО ТАМ, ГДЕ БЫЛ ПРЕФИКС ФОРМЫ.
//
// topic_kind по смыслу — «что человек выбрал в форме», и «Plan» принимает его
// именно как ФАКТ: по нему включается режим выгрузки, и признак «просят
// помочь с запросом» его намеренно НЕ перебивает (перебивает он только
// догадку по плейбуку).
//
// В личке PREFIXES пуст, формы нет вовсе, и сюда уезжала ВСЯ первая строка
// свободного текста. Следствий два, оба тихие:
//   — «Подскажи, нужно ли заводить запрос на выгрузку, если данные нужны
//     разово?» включало полный режим выгрузки: две лишние статьи, +4500
//     токенов правил и требование блока ТЗ — на вопрос, а не на заявку.
//     Ровно то, что комментарий про isExport обещает не допускать;
//   — «как написать select, чтобы выгрузить…» тоже уезжало в режим, и
//     погасить его было нечем: догадкой он не считался. То есть живой
//     отказ 2026-08-27 в личке остался невылеченным.
// Префикса не было — темы нет. Шапку, если её вставили в личку целиком,
// «Plan» и так восстановит из первой строки самого обращения.
const topicKind = !topic ? '' :
  (authorAt === -1 ? afterPrefix : afterPrefix.slice(0, authorAt))
    .replace(/[\s|·—-]+$/, '').trim();

// Автор — из шапки формы, а НЕ из sender_name: постит intake-воркфлоу, и
// sender_name это он, а не человек, задавший вопрос. Имя может быть и логином
// (@i.ivanov), и двумя словами (@Anna Sokolova), поэтому берём всё после «@»
// до конца шапки и ограничиваем тремя словами: длиннее — это уже не имя.
const atPos = afterPrefix.indexOf('@');
const formAuthor = atPos === -1
  ? ''
  : afterPrefix.slice(atPos + 1).split(/[|·]/)[0].trim()
      .split(/\s+/).slice(0, 3).join(' ');

const formDomain = section(/домен/i);

// Ссылки на отчёт. Берём из полей, где метка говорит про ссылку или отчёт,
// а если таких полей нет — из всего текста: ссылку могли просто вставить
// в вопрос. Две штуки максимум: больше — это уже не «вопрос по отчёту».
//
// ССЫЛКА НА ЮНИТ ОТЧЁТОМ НЕ СЧИТАЕТСЯ, И ЭТО НЕ МЕЛОЧЬ.
// Живой прогон 03.09: в личке заказчик прислал название команды ссылкой
// на структуру, «из всего текста» подобрало её как ссылку на отчёт, и дальше
// по цепочке `report_url` → `asksReport` бот отвечал про отчёт, которого
// нет в базе, вместо запроса про команду: «Разбор витрины за ответ про
// отчёт я подменять не буду». Ссылка на юнит — это адрес ПОДРАЗДЕЛЕНИЯ,
// у неё свой путь в ядре (справочник `id` → `rk`), и подменять им вопрос
// про отчёт нельзя ни в какую сторону.
const linkFields = sections
  .filter((s) => /ссылк|отч[её]т|дашборд|отчет/i.test(s.label))
  .map((s) => s.value)
  .join('\n');
const urls = (String(linkFields || message).match(/https?:\/\/\S+/g) || [])
  .map((u) => u.replace(/[),.;]+$/, ''))
  .filter((u) => !UNIT_LINK_RE.test(u));
const reportUrl = urls.slice(0, 2);

// Текст вопроса. Пусто — берём весь пост без шапки: терять вопрос из-за
// нового варианта формы нельзя, а пустой вопрос читается как «бот не знает».
const questionText = section(/вопрос|проблем|задач|запрос/i)
  || message.split('\n').slice(1).join('\n').trim()
  || message.trim();

// Передача данных за пределы группы компаний.
//
// Единственное поле формы, у которого цена ошибки — не «черновик получился
// хуже», а файл, ушедший наружу без согласования ИБ. В фидбеке аналитика
// такой ответ стоял в 5 обращениях из 22 выгрузок, и в 4 из них правильным
// ответом было «сначала согласование в ~sec_analytics_ask». Правило было
// отдано модели словами, и она его пропускала — как пропускала и лимит
// итераций, и мастеров домена. Поэтому признак считает код.
//
// РАЗБОР ИДЁТ ПО СТРОКАМ, А НЕ ПО sections. Подпись этого поля —
// «Выгрузка нужна для использования исключительно внутри группы компаний:» —
// это 71 символ, а LABEL_RE ограничен 60: в sections она не попадает вовсе
// и молча приклеивается значением к предыдущему полю. Поднимать лимит
// нельзя: длинная строка вопроса, кончающаяся двоеточием, начала бы резать
// question_text. Дешевле разобрать это одно поле отдельно.
//
// ПОЛЯРНОСТЬ ВЫВОДИТСЯ ИЗ ПОДПИСИ, А НЕ УГАДЫВАЕТСЯ ПО ОТВЕТУ. Сейчас форма
// спрашивает «нужна исключительно внутри группы компаний», и «нет» там
// означает передачу наружу. Переформулируют в «данные передаются за пределы
// контура» — и то же «нет» будет означать ровно обратное. Подпись, из которой
// полярность не читается, даёт «не разобрано», а не догадку: перепутанная
// полярность здесь тише и дороже всего остального в этом флоу.
// Кириллический класс выписан явно: \w в JS — это [A-Za-z0-9_], и «групп\w*»
// не совпадает с «группы» НИКОГДА. Та же ошибка, что \b перед кириллицей,
// и такая же тихая: проверка по подстроке была бы зелёной.
const EXT_LABEL_RE = /групп[а-яё]*\s+компан|контур|за\s+предел|третьим\s+лицам|внешн|подрядчик/i;
const EXT_INSIDE_RE = /исключительно\s+внутри|только\s+внутри|внутри\s+групп/i;
const EXT_OUTSIDE_RE = /за\s+предел|вне\s+контур|третьим\s+лицам|внешн|подрядчик/i;
// Границы слова через \b здесь не годятся: в JS они определены по ASCII,
// и \bда перед кириллицей не совпадает никогда — ровно на этом уже один раз
// молча потерялся разбор шапки формы.
const EXT_YES_RE = /^да(?:[\s,.:;!)]|$)/i;
const EXT_NO_RE = /^нет(?:[\s,.:;!)]|$)/i;

let externalTransfer = '';
let externalTransferRaw = '';
{
  const lines = message.split('\n')
    .map((l) => l.replace(/^[\s>*_#`~]+/, '').replace(/[\s*_`~]+$/, '').trim());
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    // Двоеточие обязательно: так отсекается проза заказчика, где «группа
    // компаний» может встретиться в самом вопросе. Подпись формы его несёт.
    if (!l.endsWith(':') || !EXT_LABEL_RE.test(l)) continue;
    const label = l.slice(0, -1).trim();
    let answer = '';
    for (let j = i + 1; j < lines.length; j++) {
      if (!lines[j]) continue;
      // Следующая подпись вместо ответа значит, что поле оставили пустым.
      answer = lines[j].endsWith(':') ? '' : lines[j];
      break;
    }
    const yes = EXT_YES_RE.test(answer);
    const no = EXT_NO_RE.test(answer);
    if (EXT_INSIDE_RE.test(label)) externalTransfer = no ? 'yes' : yes ? 'no' : '';
    else if (EXT_OUTSIDE_RE.test(label)) externalTransfer = yes ? 'yes' : no ? 'no' : '';
    externalTransferRaw = (label + ': ' + answer).replace(/\s+/g, ' ').slice(0, 200);
    break;
  }
}

// Готовая строка для промпта роутера: код читает поля, промпт читает текст.
const formContext = [
  topicKind ? 'Тема обращения (выбрана человеком в форме): ' + topicKind : '',
  formDomain ? 'Домен (выбран человеком в форме): ' + formDomain : '',
  reportUrl.length ? 'Ссылка на отчёт из формы: ' + reportUrl.join(' ') : '',
].filter(Boolean).join('\n');

// Порядок проверок — от самых дешёвых и однозначных к содержательным, чтобы
// в reason попадала первая настоящая причина, а не последняя по списку.
let reason = '';
if (!message.trim()) {
  reason = 'пустое сообщение';
} else if (String(post.type ?? '')) {
  // Системные сообщения (вход-выход в канал, смена темы) имеют непустой
  // type вида system_*. Отвечать на них нечего.
  reason = 'системное сообщение: ' + post.type;
} else if (DROP_BOT && String(post.props?.from_bot ?? '') === 'true') {
  reason = 'сообщение бота';
} else if (REQUIRE_ROOT && isReply && !isFollowUp) {
  // Реплика в треде обращением не является — если только это не продолжение
  // разговора: ответ на уточнение бота или прямое упоминание.
  reason = 'реплика в треде';
} else if (PREFIXES.length && !topic && !isFollowUp) {
  // Префикс формы требуется только от НОВОГО обращения. Продолжение разговора
  // приходит обычным текстом: человек отвечает на вопрос бота или зовёт его
  // тегом — требовать от такой реплики шапку intake-формы бессмысленно.
  // Обращения приходят из intake-воркфлоу с префиксом темы. Всё остальное —
  // обсуждение вокруг обращения либо вопрос к чужой команде HC Data.
  reason = 'не наша тема: ' + (head.slice(0, 60) || '(пусто)');
} else if (REQUIRE_DM &&
           String(src.channel_type ?? data.channel_type ?? post.channel_type ?? '') !== 'D') {
  reason = 'не личный диалог';
} else if (ALLOWLIST.length &&
           !ALLOWLIST.includes(String(src.sender_name ?? '').replace(/^@/, ''))) {
  reason = 'отправитель не в списке';
}

return [{ json: {
  event: src.event ?? data.event ?? '',
  post,
  // В ядро уходит ПОЛНЫЙ пост, а не question_text: поля формы для автора
  // содержательны (у выгрузки в них вся суть запроса), и урезать вход модели
  // здесь нечего — экономия нулевая, а риск потерять условие задачи есть.
  question: message,
  topic,
  // Разобранная форма. Пустые значения — норма: в личке формы нет вовсе,
  // а вариант формы мог измениться. Поэтому form_parsed — отдельный флаг,
  // и по нему видно, разбор промахнулся или полей просто не было.
  topic_kind: topicKind,
  form_author: formAuthor,
  form_domain: formDomain,
  report_url: reportUrl,
  question_text: questionText,
  form_context: formContext,
  // 'yes' — файл уходит за пределы группы компаний, 'no' — только внутри,
  // '' — поля в форме не нашлось или полярность подписи не читается.
  // Три состояния, а не булево: «не разобрано» и «внутри» — разные вещи,
  // и подставлять второе вместо первого значит молча снять требование ИБ.
  external_transfer: externalTransfer,
  // Что именно прочитано. Диагностика на случай, когда форму переформулируют:
  // по этому полю видно, подпись не нашлась или не разобрался ответ.
  external_transfer_raw: externalTransferRaw,
  form_parsed: Boolean(formDomain || reportUrl.length || sections.length),
  // Продолжение разговора: по нему адаптер решает, дочитывать ли тред.
  is_follow_up: isFollowUp,
  mentioned,
  thread_root: threadRoot,
  channel_id: post.channel_id ?? data.channel_id ?? '',
  channel_name: src.channel_name ?? data.channel_name ?? '',
  sender_name: String(src.sender_name ?? '').replace(/^@/, ''),
  pass: !reason,
  reason,
} }];

// Переписка одной строкой на реплику, в порядке времени.
//
// ЧИТАЕТСЯ КАК ДИАЛОГ, А НЕ КАК JSON. Автору нужно понять, о чём договорились:
// кто спросил, что бот уточнил, что человек ответил. Роли подписаны словами —
// «бот» и логин человека, — потому что по id участника модель не отличит
// своё сообщение от чужого и начнёт отвечать на собственный вопрос.
const MAX_POSTS = 40;
const MAX_CHARS = 6000;

let posts = [];
try {
  const r = $('Get thread').first().json;
  const order = Array.isArray(r.order) ? r.order : [];
  const byId = r.posts || {};
  posts = (order.length ? order.map((id) => byId[id]) : Object.values(byId))
    .filter(Boolean)
    .sort((a, b) => (a.create_at || 0) - (b.create_at || 0));
} catch (e) {
  // Узел чтения не выполнялся — обычное новое обращение, переписки нет.
  // Это НОРМАЛЬНЫЙ путь, а не отказ.
  return [{ json: { thread: '', thread_posts: 0, thread_state: 'not_asked' } }];
}

if (!posts.length) {
  // Ответ пришёл, а постов в нём нет — это НЕ «переписки не было».
  // Молча отдать пустую строку значит выдать отказ ручки за отсутствие
  // контекста, и автор ответит на реплику, не зная вопроса.
  return [{ json: { thread: '', thread_posts: 0, thread_state: 'empty' } }];
}

const lines = [];
for (const p of posts.slice(-MAX_POSTS)) {
  const who = String((p.props || {}).from_bot || '') === 'true' ? 'бот' :
    ('@' + String((p.props || {}).override_username || p.user_id || 'человек'));
  const text = String(p.message || '').trim();
  if (text) lines.push(who + ': ' + text);
}
let thread = lines.join('\n\n');
let cut = 0;
if (thread.length > MAX_CHARS) {
  // Режем НАЧАЛО, а не хвост: последние реплики — это то, на что отвечаем.
  cut = thread.length - MAX_CHARS;
  thread = '…(начало переписки обрезано, ' + cut + ' символов)\n\n' +
           thread.slice(-MAX_CHARS);
}
return [{ json: {
  thread,
  thread_posts: lines.length,
  thread_state: cut ? 'trimmed' : 'ok',
} }];

const CONF = { high: 'высокая', medium: 'средняя', none: 'нет ответа' };
// Винительный падеж для строки «бот заявил …»: «заявил высокая» читается
// как опечатка и отвлекает от смысла строки.
const CONF_ACC = { high: 'высокую', medium: 'среднюю', none: '«нет ответа»' };
// Светофор у уверенности. Решение пользователя: по одному взгляду на канал
// должно быть видно, проблемный это тред или ответ можно брать и копировать,
// не разворачивая служебный блок.
// Белый — для unknown: модель отклонилась от формата, и это не «посередине»,
// а «непонятно»; рядом в треде печатается parse_error.
// Светофор — эмодзи пака (`иконки/`): цвет кепки, зелёная / жёлтая / красная,
// светло-серая у unknown. Шапка живёт в канале джуна и наружу не уходит,
// поэтому здесь наши эмодзи, а не юникод; в черновике заказчику — только
// юникод, см. правило про 🔒 в «Где это живёт в коде» пака.
const CONF_DOT = { high: ':bully_high:', medium: ':bully_mid:', none: ':bully_none:' };
const confDot = (k) => CONF_DOT[k] || ':bully_unknown:';

// Корневой пост: строка обращения в канале джуна.
//
// ОБРАЩЕНИЕ НЕ ЦИТИРУЕТСЯ ЦЕЛИКОМ. Раньше здесь печаталось '> ' + a.question,
// а question — это весь пост intake-формы: шапка, «Выбери домен», ссылка на
// отчёт и текст вопроса. Именно эта цитата разгоняла посты к лимиту 4000
// символов, на котором пост черновика падал. Но и совсем без темы канал читался
// как список ссылок: чтобы понять, о чём обращение, приходилось открывать
// тред. Поэтому здесь одна строка — начало вопроса из формы, обрезанное
// по длине; полный текст остаётся по ссылке за один клик.
const a = $json;
const src = $('Guard channel').first().json;
const post = src.post ?? {};

const link = post.id
  ? 'https://time.tbank.ru/tinkoff/pl/' + post.id
  : '';

// Светофор приклеен к теме, а не отделён точкой: он читается как значок
// строки, а не как её первое поле.
const head = [
  confDot(a.confidence_key) + ' **' +
    (src.topic_kind || 'Вопрос из ~' + (src.channel_name || 'hr-report-ask')) + '**',
  src.form_author ? '@' + src.form_author : '',
  link ? '[открыть обращение](' + link + ')' : '',
].filter(Boolean).join(' · ');

const lines = [head];

const SUBJ_MAX = 160;
let subj = String(src.question_text ?? '').replace(/\s+/g, ' ').trim();
if (subj.length > SUBJ_MAX) subj = subj.slice(0, SUBJ_MAX).trimEnd() + '…';
if (subj) lines.push('_' + subj + '_');

// Уверенность и, если она понижена кодом, — чем именно. Причина здесь, а не
// только в треде: по ней джун решает, разворачивать тред или брать черновик
// как есть, и ради этого решения пост и существует.
let conf = 'Уверенность: **' + (CONF[a.confidence_key] || a.confidence || '—') + '**';
if (a.confidence_capped) {
  conf += ' ← бот заявил ' + (CONF_ACC[a.confidence_claimed] || a.confidence_claimed);
}
lines.push(conf);
if (a.confidence_capped_reason) lines.push('_Почему: ' + a.confidence_capped_reason + '_');
if (a.parse_error) lines.push(':bully_warn: **Разбор ответа:** ' + a.parse_error);

// Что искать в треде. Названо явно: свёрнутый тред в Mattermost показывает
// число ответов, а не их состав, и без этой строки непонятно, есть ли там
// готовое к отправке сообщение.
lines.push('_В треде: разбор · сообщение заказчику' +
  (String(a.tech_spec ?? '').trim() ? ' · ТЗ для аналитика' : '') + '._');

// Кроме текста шапка отдаёт контекст для кнопок обратной связи: нода поста
// подставляет его в context кнопок, а вебхук получает обратно как есть.
// thread_id — id ИСХОДНОГО обращения: по нему оценка склеивается с обращением
// в телеметрии. Пустой (обращение без id) — оценка всё равно запишется,
// просто не привяжется к треду, и это видно в самой записи.
//
// ТЕМА УЕЗЖАЕТ ПОЛНЫМ ЗАГОЛОВКОМ, а не куском после префикса.
//
// В шапке печатается человекочитаемая часть («Выгрузка данных»), и раньше
// ровно она уходила в контекст кнопки под именем `kind`. В телеметрии `kind` —
// аналитический ключ (`export`), тот же, что пишет обращение; в итоге одна
// колонка держала два словаря сразу, и разбивка по темам разошлась бы на
// «обращения» и «оценки» как на разные темы. Классификацию делает вебхук
// кнопок — он собирается из того же списка тем, что и нормализатор, — а бот
// по-прежнему про список тем не знает и отдаёт заголовок как есть.
const topicTitle = [String(src.topic ?? '').trim(), String(src.topic_kind ?? '').trim()]
  .filter(Boolean).join(' ').trim();

return [{ json: {
  text: lines.join('\n'),
  thread_id: String(post.id ?? ''),
  topic: topicTitle,
  confidence_key: String(a.confidence_key ?? ''),
} }];

// Разбивка длинного текста на посты Mattermost.
//
// 3900, а не 4000: лимит считается сервером в символах, и запас нужен на
// маркер «(1/2)» и на markdown, который мы добавляем сами. Упереться в лимит
// повторно значит снова уронить последний узел — уже после того, как ядро
// отработало и ответ собран.
const MM_LIMIT = 3900;
// Больше четырёх сообщений на один черновик — это не длинный ответ, а сбой:
// спамить канал джуна нельзя, поэтому хвост обрезается с явной пометкой.
const MM_MAX_PARTS = 4;

function mmChunks(text) {
  const s = String(text ?? '').trim();
  if (s.length <= MM_LIMIT) return [s];

  const chunks = [];
  let rest = s;
  // Режем по границе строки, а если её нет — по слову: разрыв посреди
  // markdown-ссылки или таблицы ломает разметку в обеих половинах.
  while (rest.length > MM_LIMIT && chunks.length < MM_MAX_PARTS - 1) {
    let at = rest.lastIndexOf('\n', MM_LIMIT);
    if (at < MM_LIMIT * 0.5) at = rest.lastIndexOf(' ', MM_LIMIT);
    if (at < MM_LIMIT * 0.5) at = MM_LIMIT;
    chunks.push(rest.slice(0, at).trimEnd());
    rest = rest.slice(at).trimStart();
  }
  if (rest.length > MM_LIMIT) {
    const kept = rest.slice(0, MM_LIMIT - 80).trimEnd();
    rest = kept + '\n\n✂️ обрезано ' + (rest.length - kept.length) +
           ' символов: лимит поста Mattermost.';
  }
  chunks.push(rest);
  return chunks;
}

// Нумерация обязательна: без неё несколько постов подряд читаются как
// несколько разных ответов на одно обращение.
function mmSplit(text) {
  const chunks = mmChunks(text);
  if (chunks.length < 2) return chunks;
  return chunks.map((c, i) => '**(' + (i + 1) + '/' + chunks.length + ')**\n' + c);
}

// Нода mattermost отправляет по посту на входной элемент, поэтому разбивка
// возвращается элементами, а порядок сохраняется исполнением по элементам.
const mmItems = (text) => mmSplit(text).map((t) => ({ json: { text: t } }));

// РАЗНЫЕ БЛОКИ — РАЗНЫМИ ПОСТАМИ.
//
// Сообщение заказчику и ТЗ для аналитика адресованы разным людям, и джун
// пересылает первое, не трогая второе. Пока они ехали одним постом, переслать
// было нечего: ни целиком, ни куском. Отдельный пост копируется целиком
// и кнопкой «Copy Text», а заголовок остаётся первой строкой — его джун
// снимает одним движением, в отличие от чересполосицы бизнеса и техники.
//
// Общий предохранитель на число постов свой: посекционного мало, три секции
// по четыре части — это двенадцать сообщений подряд в канале джуна.
const MM_MAX_POSTS = 6;

function mmSections(sections) {
  const items = [];
  let dropped = 0;
  for (const s of sections) {
    const body = String(s.body ?? '').trim();
    if (!body) continue;
    const chunks = mmChunks(body);
    chunks.forEach((c, i) => {
      const title = String(s.title ?? '').trim();
      const mark = chunks.length > 1 ? ' (' + (i + 1) + '/' + chunks.length + ')' : '';
      const head = title ? '**' + title + mark + '**\n' : (mark ? '**' + mark.trim() + '**\n' : '');
      if (items.length < MM_MAX_POSTS) items.push({ json: { text: head + c } });
      else dropped++;
    });
  }
  // Молча потерянный хвост — тот же тихий отказ: по виду канала ответ полный.
  if (dropped && items.length) {
    items[items.length - 1].json.text +=
      '\n\n✂️ не отправлено частей: ' + dropped + ' (предел ' + MM_MAX_POSTS +
      ' сообщений на одно обращение).';
  }
  return items.length ? items : [{ json: { text: '_ответ пустой_' } }];
}

const CONF = { high: 'высокая', medium: 'средняя', none: 'нет ответа' };
// Винительный падеж для строки «бот заявил …»: «заявил высокая» читается
// как опечатка и отвлекает от смысла строки.
const CONF_ACC = { high: 'высокую', medium: 'среднюю', none: '«нет ответа»' };
// Светофор у уверенности. Решение пользователя: по одному взгляду на канал
// должно быть видно, проблемный это тред или ответ можно брать и копировать,
// не разворачивая служебный блок.
// Белый — для unknown: модель отклонилась от формата, и это не «посередине»,
// а «непонятно»; рядом в треде печатается parse_error.
// Светофор — эмодзи пака (`иконки/`): цвет кепки, зелёная / жёлтая / красная,
// светло-серая у unknown. Шапка живёт в канале джуна и наружу не уходит,
// поэтому здесь наши эмодзи, а не юникод; в черновике заказчику — только
// юникод, см. правило про 🔒 в «Где это живёт в коде» пака.
const CONF_DOT = { high: ':bully_high:', medium: ':bully_mid:', none: ':bully_none:' };
const confDot = (k) => CONF_DOT[k] || ':bully_unknown:';

// Ответы в тред к шапке обращения.
//
// РАЗНЫЕ БЛОКИ — РАЗНЫМИ ПОСТАМИ, и это свойство сохраняется: джун копирует
// сообщение заказчику ЦЕЛИКОМ кнопкой «Copy Text» и отправляет в тред
// обращения, ТЗ оставляет себе, служебное не пересылает никогда. Пока они
// ехали одним постом, копировать было нечего — ни целиком, ни куском.
//
// Входной элемент здесь — ответ Mattermost на публикацию шапки, поэтому
// разбор берётся у ядра по имени ноды, а не из $json.
const a = $('Call core').first().json;

const parts = [];

// Передача вне контура — первой строкой, раньше основания и источников.
// Всё остальное в этом блоке говорит, насколько черновику можно верить;
// эта строка говорит, что его нельзя отправлять как есть. Порядок здесь
// и есть способ это различить.
if (a.registry_error) {
  parts.push(':bully_flag: **' + a.registry_error + '.** Это поломка ДОСТУПА к базе, ' +
    'а не пробел в ней: статьи не выбирались вовсе, мастера домена ' +
    'не добирались, отвечать было не по чему. Проверить, что `kb/index.md` ' +
    'лежит по этому пути в GitLab-проекте бота и доступен его Service ' +
    'Account. До починки бот не отвечает ни на что.');
}

if (a.ib_missing) {
  parts.push(':bully_lock: **Передача вне группы компаний, а согласования ИБ ' +
    'в черновике нет.** В форме указано, что данные уходят наружу — ' +
    'дописать перед отправкой: файл не передаём, пока ИБ не согласовала, ' +
    'заявка в ~sec_analytics_ask.');
} else if (a.ib_required) {
  parts.push(':bully_lock: **Передача вне группы компаний:** согласование ИБ ' +
    '(~sec_analytics_ask) обязательно, в черновике оно названо.');
}

// Маршрут — после строки ИБ, но до основания: это не оценка доверия
// к черновику, а факт про обращение, и джуну он нужен даже тогда, когда
// автор им не воспользовался (проверить это кодом нечем — см. «Parse answer»).
//
// Дата подтверждения печатается ЗДЕСЬ и только здесь. В черновик она
// не идёт — это служебное, — а джун единственный, кто заметит, что маршрут
// протух, и поправит строку в реестре.
// Названный, но не подобранный эксперт — раньше маршрута и основания:
// это не «насколько верить черновику», а «черновик нельзя отправлять как есть».
if (a.draft_no_active_filter) {
  parts.push(':bully_flag: **В запросе нет фильтра активной численности.** Витрина ' +
    'хранит и уволенных, поэтому запрос вернёт завышенное число, ' +
    'и по виду результата это не заметно. Добавить перед отправкой: ' +
    '`active_employee_flg = 1 and company_fire_flg = 0` — или, если ' +
    'уволенные нужны намеренно, сказать об этом в ответе.');
}

if (a.sens_unmarked) {
  // ПОЛЯ НАЗЫВАЮТСЯ ПОИМЁННО. Прежняя строка сообщала только число закрытых
  // полей по каталогу, а джуну нужно знать, КАКИЕ именно остались без замка:
  // искать их глазами по составу из двадцати имён он не станет.
  //
  // И ГДЕ ИМЕННО ЗАМКА НЕТ. Ответ заказчику и ТЗ проверяются порознь:
  // без этого джун шёл в ответ, находил там замки на половине имён
  // и переставал верить строке целиком — вместе с настоящим промахом.
  const miss = Array.isArray(a.sens_unmarked_fields) ? a.sens_unmarked_fields : [];
  const where = a.sens_unmarked_where ? ' (' + a.sens_unmarked_where + ')' : '';
  parts.push(':bully_lock: **Закрыто каталогом, а замка нет' + where + ': ' +
    miss.join(', ') + '.** Поля с закрытым доступом из ответа не убираются — ' +
    'запрета нет, есть согласование, — но заказчик должен видеть, по каким ' +
    'из них оно понадобится. Пометить 🔒 рядом с полем и дописать строку ' +
    'под списком.');
}

if (a.draft_fire_by_date) {
  parts.push(':bully_flag: **Увольнения посчитаны по дате, а не по флагу.** ' +
    '`company_fire_dt` бывает проставлена на будущее — заявление написано, ' +
    'увольнение через две недели, — и такое увольнение может не состояться. ' +
    'Значит в счёт попали несвершившиеся события. Факт увольнения — ' +
    '`company_fire_flg = 1`; дата остаётся границей периода и выводимым ' +
    'значением, но не признаком.');
}

if (Array.isArray(a.draft_invented_fields) && a.draft_invented_fields.length) {
  parts.push(':bully_flag: **В черновике имена полей, которых нет в метаданных:** ' +
    a.draft_invented_fields.map((f) => '`' + f + '`').join(', ') +
    '. Ни в инвентаре каталога, ни в прочитанных статьях их не было — ' +
    'значит они выведены по смыслу, а не проверены. Заказчик прочтёт это ' +
    'как состав данных: убрать или заменить на настоящие перед отправкой.');
}

if (a.revise_dropped) {
  parts.push(':bully_flag: **Второй проход вернул текст без блоков** — оставлен ' +
    'черновик первого прохода. Значения фильтров в нём данными НЕ ' +
    'подтверждены, хотя проверка отрабатывала: покажите этот тред тому, ' +
    'кто ведёт бота.');
} else if (Array.isArray(a.revise_carried) && a.revise_carried.length) {
  const NAMES = { tech_spec: 'ТЗ для аналитика', sources: 'источники',
                  gaps: 'чего не хватило' };
  parts.push(':bully_warn: **Второй проход не вернул: ' +
    a.revise_carried.map((k) => NAMES[k] || k).join(', ') +
    '.** Взято из первого прохода — значения фильтров там остались ' +
    'непроверенными, сверьте с блоком 🔢 ниже.');
}

if (Array.isArray(a.draft_company_filter) && a.draft_company_filter.length) {
  parts.push(':bully_flag: **В фильтре название компании:** ' +
    a.draft_company_filter.map((x) => '`' + x.field + '` = «' + x.value + '»').join(', ') +
    '. Т-Банк — это вся витрина, а не значение поля: фильтр вернёт ноль ' +
    'строк. Если речь про Т-Банк как ЮРЛИЦО — это юридическая структура, ' +
    'см. рецепт выбора структуры.');
}

// Ссылка на юнит: код сходил в справочник ЗА автора. Печатается только
// когда ссылка была — строка, которая горит всегда, перестаёт читаться.
if (a.unit_state === 'found') {
  parts.push('🔗 **Юнит по ссылке разрешён:** ключ `' + a.unit_rk +
    '`' + (a.unit_nm ? ' («' + a.unit_nm + '»)' : '') +
    '. Первый шаг рецепта выполнил код, а не автор — ключ в запросе ' +
    'подтверждён справочником.');
} else if (a.unit_state === 'not_found') {
  parts.push('🔗 **Юнит по ссылке НЕ НАЙДЕН в справочнике.** Это ответ, ' +
    'а не сбой: юнит закрыт, удалён или ссылка из другой структуры. ' +
    'В черновике должно стоять именно это, а не «уточните, где искать».');
} else if (a.unit_state === 'failed' || a.unit_state === 'never_ran') {
  parts.push(':bully_flag: **Ключ юнита по ссылке получить не удалось** (' +
    (a.unit_state === 'failed' ? 'запрос к справочнику отказал'
                               : 'узел «Resolve unit» не выполнялся') +
    '). Это поломка бота: проверьте ветку разрешения ссылки в «Support ' +
    'Bot Core» и доступ аккаунта Trino к `prod_v_dds`.');
}

if (Array.isArray(a.dd_parse_failed) && a.dd_parse_failed.length) {
  parts.push(':bully_flag: **Каталог прислал состав полей, а разбор его не увидел:** ' +
    a.dd_parse_failed.join(', ') + '. Это поломка бота, а не каталога: ' +
    'формат перечня разъехался с разбором. Реестр и доступы тут ни при чём.');
}

if (Array.isArray(a.dd_no_fields) && a.dd_no_fields.length) {
  const got = Array.isArray(a.cols_from_data) ? a.cols_from_data : [];
  const bad = Array.isArray(a.dd_bad_urn) ? a.dd_bad_urn : [];
  const tail = got.length
    ? ' Имена полей добраны из данных, так что ответ полный; не хватает ' +
      'только описаний из каталога.'
    : ' Состава полей у бота нет вовсе.';
  parts.push('🗂 **Каталог не дал состав полей:** ' + a.dd_no_fields.join(', ') +
    '.' + (bad.length
      ? ' Каталог ОТКАЗАЛ — это неверный URN в `kb/index.md` либо истёкший ' +
        'Service Account.'
      : ' Каталог ответил, но список полей пустой. Почему — по ответу ' +
        'не видно: прогнать фазу H в «DD Recon».') + tail);
}

if (a.draft_asks_date === true) {
  parts.push(':bully_flag: **Бот переспрашивает про дату, которой заказчик не называл.** ' +
    'Не назвал период — значит нужно состояние на сейчас: актуальный срез ' +
    'ставится сам, и это не пробел запроса. Лишний вопрос стоит заказчику ' +
    'круга ожидания ради очевидного ответа.');
}

if (Array.isArray(a.draft_key_unlabeled) && a.draft_key_unlabeled.length) {
  parts.push(':bully_flag: **Ключ в запросе не подписан названием:** `' +
    a.draft_key_unlabeled.join('`, `') + '`. Название юнита код получил ' +
    'из справочника, и оно должно стоять комментарием рядом с фильтром — ' +
    'иначе аналитик не проверит, тот ли это юнит, а через месяц по хешу ' +
    'никто не поймёт, что выгружалось.');
}

if (Array.isArray(a.draft_foreign_ids) && a.draft_foreign_ids.length) {
  parts.push(':bully_flag: **В ответе идентификаторы, которых заказчик не называл:** ' +
    a.draft_foreign_ids.map((x) => '`' + x + '`').join(', ') +
    '. Данные их не подтверждали, и каждый — чужое подразделение. ' +
    'Выбрать из хешей человек не может: либо ключ подтверждён и стоит ' +
    'в фильтре молча, либо его нет и надо спросить НАЗВАНИЕ.');
}

if (Array.isArray(a.draft_placeholders) && a.draft_placeholders.length) {
  parts.push(':bully_flag: **В запросе остались плейсхолдеры:** ' +
    a.draft_placeholders.map((h) => '`' + h + '`').join(', ') +
    '. ТЗ — это готовый SQL, который заказчик копирует и запускает; ' +
    'с плейсхолдером он не запустится, а подставить их заказчику нечем.');
}

if (Array.isArray(a.draft_own_tools) && a.draft_own_tools.length) {
  parts.push(':bully_flag: **В черновике предложен инструмент аналитика:** ' +
    a.draft_own_tools.join(', ') +
    '. У коллеги его нет — заменить на состав полей из ответа или убрать.');
}

if (Array.isArray(a.experts_invented) && a.experts_invented.length) {
  parts.push(':bully_flag: **В черновике назван эксперт, которого код не подбирал:** ' +
    a.experts_invented.join(', ') +
    '. Ни одно ключевое слово маршрута под этот вопрос не совпало — ' +
    'проверьте, тот ли это человек, перед отправкой.');
}

if (Array.isArray(a.routes) && a.routes.length) {
  const line = a.routes.map((r) => {
    const addr = [r.who, r.where].filter(Boolean).join(', ') || 'адресат не указан';
    const by = Array.isArray(r.matched) && r.matched.length
      ? ` — по слову «${r.matched[0]}»` : '';
    const when = r.checked ? `, маршрут проверен ${r.checked}` :
      ', ДАТА ПОДТВЕРЖДЕНИЯ НЕ УКАЗАНА';
    return `${addr}${by}${when}`;
  }).join(' · ');
  parts.push(':bully_expert: **Позвать эксперта по теме:** ' + line);
}

// Проверка значений в данных — до основания: она отвечает не «насколько
// верить черновику вообще», а «сходится ли конкретное значение фильтра,
// которое в нём названо». Без этой строки подтверждённое данными значение
// и придуманное выглядят в треде одинаково, а разница между ними — это
// разница между верной цифрой и молча неверной.
//
// Печатается ТОЛЬКО когда автор просил проверку: строка, которая горит
// на каждом обращении, перестаёт читаться — ровно так «ФИО» из шаблона
// формы обесценило подсказку про самообслуживание.
if (a.check_missed) {
  parts.push(a.check_retried
    // Доспрос был, и автор пар всё равно не назвал. Это уже не поломка
    // разбора: бот посмотрел на свой ответ второй раз и проверять
    // не нашёл чего. Значения в черновике всё равно неподтверждённые.
    ? ':bully_flag: **Значения данными не подтверждены.** Бота переспросили, какие ' +
      'пары «поле = значение» проверить, — он не назвал ни одной' +
      (a.check_reason ? ' (' + a.check_reason + ')' : '') +
      '. Написание в черновике проверьте вручную перед отправкой.'
    : ':bully_flag: **Автор пишет, что значение не проверено, а проверка ' +
      'не запускалась.** Разбор пар «поле = значение» промахнулся' +
      (a.check_reason ? ' (' + a.check_reason + ')' : '') +
      '. Значения в черновике данными НЕ подтверждены — и это поломка бота, ' +
      'а не пробел базы: покажите этот тред тому, кто ведёт бота.');
}

// Подмена значения — раньше остальных строк проверки: она говорит не
// «насколько верить черновику», а «в запросе стоит не то, о чём просили».
if (Array.isArray(a.check_substituted) && a.check_substituted.length) {
  parts.push(':bully_flag: **В фильтре значение, которого заказчик не называл:** ' +
    a.check_substituted.map((x) => '`' + x.field + '` = «' + x.value + '»').join(', ') +
    '. Данные ответили, что слов заказчика в этом поле нет, — а в запрос ' +
    'всё равно подставлено значение из перечня. Обычно это значит, что ' +
    'выбрано не то поле: проверьте по словарю синонимов, где на самом деле ' +
    'живёт слово заказчика. Запрос выполнится и вернёт неверные цифры молча.');
}

if (a.draft_stale_caveat) {
  parts.push(':bully_warn: **В черновике осталась просьба уточнить значение через ' +
    '`select distinct`** — а значения уже сверены с данными ниже. ' +
    'Убрать перед отправкой: коллега пойдёт проверять то, что проверено.');
}

if (a.check_asked) {
  if (a.check_failed) {
    // ДВА РАЗНЫХ ДИАГНОЗА, и чинятся они в разных местах. «Column … cannot
    // be resolved» — это поле ушло в запрос к таблице, где его нет, то есть
    // поломка привязки поля к витрине, а не отказ данных. Слитые в один
    // диагноз, они отправляют чинить не то: джун идёт проверять доступы,
    // а чинить надо бота.
    const isBug = /cannot be resolved|does not exist|mismatched input/i
      .test(String(a.check_failed));
    parts.push('🔢 **Значения фильтров проверить не удалось:** ' +
      a.check_failed + '. Значение в черновике данными НЕ подтверждено — ' +
      'проверьте перед отправкой.' +
      (isBug ? ' Это ПОЛОМКА БОТА, а не отказ данных: запрос ушёл к таблице, ' +
               'в которой такого поля нет. Покажите тред тому, кто ведёт бота.'
             : ''));
  } else if (!a.check_rows) {
    parts.push('🔢 **Значения фильтров проверялись, но данные строк ' +
      'не вернули.** Значение в черновике не подтверждено.');
  } else {
    // ЧТО ЗНАЧИТ ЧИСЛО — надо сказать, а не показать. Здесь стояло
    // «сверены с данными (600 строк)», и живой вопрос был ровно такой:
    // что за 600 строк, я такого ответа не вижу. Это не строки ответа
    // и не найденные сотрудники — это размер СЛОВАРЯ ЗНАЧЕНИЙ, который
    // код вытащил из витрин, чтобы автор выбрал написание фильтра.
    // Число без единицы измерения читается как что угодно.
    const what = a.check_exact
      ? 'написание в фильтре подтвердилось дословно'
      : 'дословного совпадения не нашлось';
    parts.push('🔢 **Значения фильтров сверены с данными.** Из витрин ' +
      'поднят словарь значений (' + a.check_rows + ' вариантов по ' +
      (Array.isArray(a.check_fields) && a.check_fields.length
        ? a.check_fields.length + ' полям' : 'проверяемым полям') +
      '), ' + what + '. ' +
      (a.revised ? 'Черновик переписан по реальным значениям.'
                 : 'Правок не потребовалось.'));
  }
}

if (Array.isArray(a.confidence_basis) && a.confidence_basis.length) {
  parts.push('**Основание:** ' + a.confidence_basis.join(' · '));
}
if (a.sources) parts.push('**Источники:** ' + a.sources.replace(/\n/g, ' · '));
if (a.gaps) parts.push('**Чего не хватило:** ' + a.gaps.replace(/\n/g, ' '));

// Техническое в сообщении заказчику. Печатается списком, а не вырезается:
// вырезанное имя поля оставило бы фразу без смысла, а править текст модели
// кодом нельзя — в канал уехало бы то, чего никто не писал.
if (Array.isArray(a.draft_leaks) && a.draft_leaks.length) {
  parts.push(':bully_warn: **Вычистить перед отправкой:** ' + a.draft_leaks.join(', ') +
    ' — заказчику имена таблиц и полей не нужны.');
}

// Длина черновика. Мерит код, режет человек: править текст модели кодом
// нельзя, а молчать о полотне — значит отправить заказчику ровно то, на что
// он уже жаловался.
if (a.draft_too_long) {
  parts.push('✂️ **Черновик длинный:** ' + a.draft_too_long + ' знаков. ' +
    'Правило режима — до 1500 без списка полей; лишнее обычно это повторы ' +
    'и расшифровки очевидного.');
}

// Задача для базы — готовый список правок, а не впечатление. Собран кодом
// из фактов в «Parse answer»: см. там, почему не просьбой к модели.
// Роутер назвал путь неверно, а код восстановил его по реестру. Печатается
// джуну, а не только в телеметрию: восстановление это починка на лету,
// и если оно случается часто — чинить надо промпт роутера, а не радоваться
// тому, что статья всё-таки доехала.
if (Array.isArray(a.articles_recovered) && a.articles_recovered.length) {
  parts.push('🔁 **Путь статьи восстановлен по реестру:** ' +
    a.articles_recovered.map((r) => r.said + ' → ' + r.path).join(', ') +
    '. Роутер назвал путь неверно; статья прочитана, но промах стоит ' +
    'показать тому, кто ведёт бота.');
}

if (Array.isArray(a.kb_tasks) && a.kb_tasks.length) {
  parts.push('');
  parts.push('**Задача для базы**');
  for (const t of a.kb_tasks) parts.push('— ' + t);
}

// Заголовок ТЗ печатается только когда блок есть. Для обычного вопроса
// ТЗ не бывает вовсе, и пустой заголовок читался бы как «бот не дописал».
return mmSections([
  { title: 'Разбор', body: parts.join('\n') },
  { title: 'Сообщение заказчику — скопировать в тред',
    body: a.draft || '_черновик пустой_' },
  { title: 'ТЗ для аналитика — заказчику не отправлять', body: a.tech_spec },
]);

// Событие «бот ответил» для лога телеметрии.
//
// Ключ идемпотентности — обращение плюс версия промптов: повторный прогон
// того же обращения на той же версии перезапишет строку, а прогон после
// правки промпта добавит новую. Это ровно то, что нужно для сверки
// «правка промпта → оценки кнопками».
//
// ОДИН УЗЕЛ НА ДВА АДАПТЕРА, а не копия. Поля payload читает витрина
// по именам, и вторая копия разъехалась бы с ней молча — ровно так же,
// как разъезжались credential'ы и списки тем. Различаются адаптеры только
// именем guard'а и значением source, и оба подставляет сборщик.
//
// SOURCE РАЗДЕЛЯЕТ КАНАЛ И ЛИЧКУ, и это не украшение. У обращения из лички
// нет ни формы, ни реакций дежурного, ни задачи в трекере: время реакции,
// время решения и доля закрытых по нему не считаются вовсе. Смешать их
// с канальными значило бы разбавить каждую метрику процесса строками,
// у которых этих метрик нет. Витрина поэтому берёт обращения только
// из канала, а калибровку бота — по обоим источникам, с разрезом.
const a = $('Call core').first().json;
const src = $("Guard channel").first().json;
const postId = String((src.post ?? {}).id ?? '');

return [{ json: {
  event: 'bot_answered',
  event_id: 'bot_answered:' + postId + ':' + "91c3c4ab",
  thread_id: postId,
  event_ts: Date.now(),
  actor: 'core',
  source: "core",
  payload: {
    // Домены роутера — то, ради чего врезка и делалась.
    domains: Array.isArray(a.domains) ? a.domains : [],
    // Пара «заявлено / действует»: по ней считается калибровка модели.
    // По одному полю не видно ни завышения, ни частоты понижений.
    confidence_claimed: a.confidence_claimed || '',
    confidence_key: a.confidence_key || '',
    confidence_capped: a.confidence_capped === true,
    capped_reason: a.confidence_capped_reason || '',
    prompt_version: "91c3c4ab",
    // МОДЕЛЬ — РЯДОМ С ВЕРСИЕЙ ПРОМПТА, И ПО ТОЙ ЖЕ ПРИЧИНЕ.
    //
    // Калибровка (заявленная уверенность против действующей) — самая ценная
    // метрика проекта, и она про КОНКРЕТНУЮ модель: у другой своя манера
    // завышать. Сменить модель и не отметить это в логе значит смешать две
    // популяции в одной цифре: доля завышений поедет, а списать её будет
    // не на что. `prompt_version` этого не ловит — он хеш ПРОМПТОВ, и смена
    // модели его не двигает вовсе (2026-08-31 модель сменили, хеш не изменился).
    llm_model: "tgpt/text.instant.sota",
    is_export: a.is_export === true,
    // Из чего собран ответ: по этим числам видно, что чинить — базу или промпт.
    // Имя поля — articles_read, а не articles: support_request.sql (CTE bot)
    // читает именно $.articles_read, и расхождение имён оставило бы колонку
    // NULL даже после импорта — тихая ошибка, которую по виду флоу не увидеть.
    articles_read: Array.isArray(a.articles_read) ? a.articles_read : [],
    // dd_count — план роутера, dd_received — факт. Порознь они бесполезны:
    // отказ ветки каталога 2026-08-26 две недели выглядел в логе как норма
    // ровно потому, что писался один только план.
    dd_count: a.dd_count || 0,
    dd_received: a.dd_received || 0,
    // Узел каталога не выполнялся, хотя объекты планировались. Отдельный
    // класс отказа: чинится в n8n, а не в базе знаний.
    dd_never_ran: a.dd_never_ran === true,
    kb_tasks: Array.isArray(a.kb_tasks) ? a.kb_tasks.length : 0,
    draft_len: a.draft_len || 0,
    draft_leaks: Array.isArray(a.draft_leaks) ? a.draft_leaks.length : 0,
    // Передача вне контура. Пишется с первого дня, хотя витрина эти поля
    // пока не читает: посчитать задним числом, как часто требование ИБ
    // возникало и как часто модель его пропускала, будет уже неоткуда —
    // в отличие от BOT_USER_IDS, который фильтруется при пересчёте.
    external_transfer: a.external_transfer || '',
    ib_required: a.ib_required === true,
    ib_missing: a.ib_missing === true,
    // Маршруты — id'шниками, а не именами: имя в реестре меняется, id нет,
    // и разрез «по каким темам звали эксперта» должен пережить смену
    // человека. Пустой массив значит «слов маршрута не было», а не
    // «маршрута не существует» — таблица покрывает то, что встретилось
    // в фидбеке, и растёт по мере трафика.
    routes: (Array.isArray(a.routes) ? a.routes : []).map((r) => r.id).join(','),
    // Эксперт назван без совпадения. Считать надо с первого дня: неверное
    // имя в треде видит заказчик, и это худший класс ошибки из тех,
    // что бот вообще может сделать.
    experts_invented: (Array.isArray(a.experts_invented) ? a.experts_invented : []).length,
    draft_own_tools: (Array.isArray(a.draft_own_tools) ? a.draft_own_tools : []).length,
    // Разрешение ссылки на юнит: доля `not_found` показывает, насколько
    // живые ссылки резолвятся, доля `failed` — доступность справочника.
    // Без разреза «бот не понял ссылку» и «такого юнита нет» неразличимы.
    unit_state: String(a.unit_state || ''),
    // Плейсхолдер в готовом запросе: ТЗ, которое нельзя запустить
    // копированием. Доля показывает, держится ли правило.
    draft_placeholders:
      (Array.isArray(a.draft_placeholders) ? a.draft_placeholders : []).length,
    // Чужой ключ в ответе: заказчик его не называл, данные не подтверждали.
    // Доля показывает, держится ли запрет предлагать выбор из хешей.
    draft_foreign_ids:
      (Array.isArray(a.draft_foreign_ids) ? a.draft_foreign_ids : []).length,
    // Ключ в запросе без подписи названием. Доля показывает, держится ли
    // правило: словесные правила модель роняет, прецедентов уже восемь.
    draft_key_unlabeled:
      (Array.isArray(a.draft_key_unlabeled) ? a.draft_key_unlabeled : []).length,
    // Переспрос про дату, которой заказчик не называл. Умолчание — «на
    // сейчас»; доля показывает, держится ли оно.
    draft_asks_date: a.draft_asks_date === true,
    // Витрины, чей URN в реестре не отдал состав полей. Девятнадцать
    // из двадцати URN собраны по схеме и не подтверждены — доля показывает,
    // сколько из них реально мешает, и по каким чинить в первую очередь.
    dd_no_fields:
      (Array.isArray(a.dd_no_fields) ? a.dd_no_fields : []).length,
    // Из них — отказы каталога (404/401). Вторая половина, «колонок
    // не заведено», не чинится вовсе, и складывать их значит мерить
    // работу, которой нет.
    dd_bad_urn: (Array.isArray(a.dd_bad_urn) ? a.dd_bad_urn : []).length,
    // Худший код отказа каталога: 404/401/5xx чинятся в разных местах,
    // и разрез по коду показывает, что чинить первым.
    dd_http_status: (Array.isArray(a.dd_failed_http) && a.dd_failed_http.length
      ? Math.max(...a.dd_failed_http.map((x) => Number(x.status) || 0)) : 0),
    // Каталог прислал состав, а разбор его не увидел. Поломка бота, и она
    // обязана быть видна цифрой: сутки этот отказ выглядел молчанием
    // каталога, потому что мерить его было нечем.
    dd_parse_failed:
      (Array.isArray(a.dd_parse_failed) ? a.dd_parse_failed : []).length,
    // Запрос по сотрудникам без фильтра активности. Метрика того, насколько
    // умолчание держится: статью код добирает на каждом запросе, и если доля
    // не падает, значит одной статьи мало и правило надо усиливать иначе.
    draft_no_active_filter: a.draft_no_active_filter === true,
    // Пометка согласования доступа: каталог назвал закрытые поля, а замков
    // в составе файла нет. Заказчик согласует состав и упирается в доступ,
    // которого не ждал.
    sens_fields: a.sens_fields || 0,
    sens_unmarked: a.sens_unmarked === true,
    // Сколько закрытых полей названо БЕЗ замка. Отдельно от sens_unmarked:
    // флаг говорит «случилось», число — насколько часто и помногу ли.
    // По нему видно, работает ли правило промпта, или его роняют молча.
    sens_unmarked_fields: Array.isArray(a.sens_unmarked_fields)
      ? a.sens_unmarked_fields.length : 0,
    // Где именно замка нет: в ответе заказчику, в ТЗ или в обоих. Числом
    // это не заменить — правило промпта одно, а роняется оно в двух местах
    // по разным причинам, и чинить их надо порознь.
    sens_unmarked_where: a.sens_unmarked_where || '',
    // Поля, которые закрыл КАТАЛОГ: их нет ни в одной прочитанной статье,
    // и понижение за пустой реестр по ним не выписывается. В витрине нужны
    // для сверки: если правило начнёт срабатывать слишком часто, это будет
    // видно числом, а не по ощущению «бот стал самоувереннее».
    catalog_only_fields: Array.isArray(a.catalog_only_fields)
      ? a.catalog_only_fields.length : 0,
    // Оборотная сторона: увольнение определено ПО ДАТЕ, а не по флагу.
    // Дата бывает проставлена на будущее, и такое увольнение может
    // не состояться — в счёт уезжают несвершившиеся события.
    draft_fire_by_date: a.draft_fire_by_date === true,
    // Название своей компании значением фильтра: «уволились из Тбанка» —
    // это вся витрина, а не значение поля.
    draft_company_filter:
      (Array.isArray(a.draft_company_filter) ? a.draft_company_filter : []).length,
    // Имена полей, которых не было ни в каталоге, ни в статьях. Заказчик
    // читает их как состав данных, а по виду черновика настоящее имя поля
    // от правдоподобного не отличить.
    draft_invented_fields:
      (Array.isArray(a.draft_invented_fields) ? a.draft_invented_fields : []).length,
    // Что потерял второй проход и пришлось добрать из первого. Доля показывает,
    // держит ли модель формат правки; revise_dropped — полный слом формата.
    revise_carried: (Array.isArray(a.revise_carried) ? a.revise_carried : []).length,
    revise_dropped: a.revise_dropped === true,
    // Резолв путей роутера. Числами, а не списками: витрине нужна доля,
    // а сами пути читает джун в треде.
    articles_recovered:
      (Array.isArray(a.articles_recovered) ? a.articles_recovered : []).length,
    articles_by_id: a.articles_by_id || 0,
    // Проверка значений в данных — она идёт ПОСЛЕ автора. Четыре числа,
    // а не одно: «автор не просил» (0 пар), «просил, но запрос отказал»,
    // «проверили, строк нет» и «проверили, черновик переписан» чинятся
    // в разных местах, а слитые в одну колонку неразличимы — ровно как
    // до 2026-08-27 были неразличимы ddFailed и ddMissing.
    check_asked: a.check_asked || 0,
    check_skipped: a.check_skipped || 0,
    check_rows: a.check_rows || 0,
    check_failed: a.check_failed || '',
    // Подтвердилось ли значение ДОСЛОВНО. Отдельно от check_rows: строки
    // вернулись — это «данные ответили», точное совпадение — «ответ был
    // тот самый». Доля дословных подтверждений и есть метрика того,
    // насколько автор угадывает написание с первого раза.
    check_exact: a.check_exact || 0,
    // ПОТОЛОК ДОСТИГНУТ: по скольким полям пришло ровно столько строк,
    // сколько разрешает LIMIT. Это измерение НАШЕГО лимита, а не
    // кардинальности поля — доля растёт, значит потолок пора поднимать.
    check_rows_capped: a.check_rows_capped || 0,
    // По скольким «витрина.поле» поднимался словарь значений. Отдельно
    // от check_rows: строки — это размер словаря, а не число полей.
    check_fields: (Array.isArray(a.check_fields) ? a.check_fields : []).length,
    // Ссылка на юнит: '' / 'management' / 'functional'. Отдельный класс
    // обращений со своим переходом id → rk через справочник.
    unit_link: a.unit_link || '',
    // Реестр не прочитан: поломка доступа к базе. Отдельный класс — по нему
    // видно, что бот стоял, а не отвечал «в базе нет ответа».
    registry_error: a.registry_error || '',
    // ПОДМЕНА значения. Отдельно от check_exact: там «ответ был тот самый»,
    // здесь «данные сказали, что такого значения нет, а в фильтр всё равно
    // уехало чужое». Единственный случай, когда проверка значений работает
    // хуже своего отсутствия, — значит мерить её надо с первого дня.
    check_substituted:
      (Array.isArray(a.check_substituted) ? a.check_substituted : []).length,
    // Черновик просит проверить то, что уже проверено. Метрика того,
    // держится ли запрет в промпте: если доля не падает, правило надо
    // усиливать не формулировкой.
    draft_stale_caveat: a.draft_stale_caveat === true,
    // Разбор пар промахнулся: автор говорит «не проверено», а проверка
    // не запускалась. Каждый такой промах до сих пор был тихим и находился
    // только глазами по логу n8n — теперь он считается.
    check_missed: a.check_missed === true,
    // Понадобился ли доспрос. Доля показывает, насколько часто автор
    // не называет пары сам: растёт — надо чинить его промпт, а не разбор.
    check_retried: a.check_retried === true,
    check_reason: a.check_reason || '',
    // Доля правок от числа проверок отвечает на вопрос, стоит ли второй
    // проход своих токенов: правок нет вовсе — значит данные ничего
    // не меняли, и цикл можно гасить.
    revised: a.revised === true,
    // Витрины, чью статью автор прочитал, а состав полей не получил.
    // Числом, а не списком: разрез «как часто бот отвечал, не видя
    // инвентаря» — это метрика полноты, а какие именно витрины,
    // разбирается по конкретному треду.
    tables_no_meta: (Array.isArray(a.tables_no_meta) ? a.tables_no_meta : []).length,
    // Просили помочь с запросом. Отдельный тип обращения, которого
    // в разрезе по темам формы нет вовсе: в форме такой темы не существует,
    // а в личке и чате формы нет.
    is_query_help: a.is_query_help === true,
    // Доля пустых планов — метрика качества роутера, и мерить её надо
    // с первого дня: задним числом «роутер промахнулся» и «в базе нет
    // ответа» по логу неразличимы.
    router_empty: a.router_empty === true,
    // Роутер назвал тему, но ни одной статьи. Отдельной колонкой,
    // потому что это разные починки: `router_empty` чинят словами
    // в таблице «Домены», а это — мастерами домена.
    router_domain_only: a.router_domain_only === true,
    parse_error: a.parse_error || '',
    // Тоже читается витриной ($.router_error) — раньше не писался вовсе.
    router_error: a.router_error || '',
    // Домен глазами заказчика против доменов бота — расхождение видно
    // без обращения к базе знаний.
    form_domain: a.form_domain || '',
    // Откуда пришло обращение. Дублируется в payload намеренно: колонка
    // source в логе служебная (её ставит нормализатор и может переопределить),
    // а разрез «канал против лички» — содержательный, и терять его при
    // пересчёте витрины нельзя.
    channel_kind: "core",
  },
} }];

// Разбивка длинного текста на посты Mattermost.
//
// 3900, а не 4000: лимит считается сервером в символах, и запас нужен на
// маркер «(1/2)» и на markdown, который мы добавляем сами. Упереться в лимит
// повторно значит снова уронить последний узел — уже после того, как ядро
// отработало и ответ собран.
const MM_LIMIT = 3900;
// Больше четырёх сообщений на один черновик — это не длинный ответ, а сбой:
// спамить канал джуна нельзя, поэтому хвост обрезается с явной пометкой.
const MM_MAX_PARTS = 4;

function mmChunks(text) {
  const s = String(text ?? '').trim();
  if (s.length <= MM_LIMIT) return [s];

  const chunks = [];
  let rest = s;
  // Режем по границе строки, а если её нет — по слову: разрыв посреди
  // markdown-ссылки или таблицы ломает разметку в обеих половинах.
  while (rest.length > MM_LIMIT && chunks.length < MM_MAX_PARTS - 1) {
    let at = rest.lastIndexOf('\n', MM_LIMIT);
    if (at < MM_LIMIT * 0.5) at = rest.lastIndexOf(' ', MM_LIMIT);
    if (at < MM_LIMIT * 0.5) at = MM_LIMIT;
    chunks.push(rest.slice(0, at).trimEnd());
    rest = rest.slice(at).trimStart();
  }
  if (rest.length > MM_LIMIT) {
    const kept = rest.slice(0, MM_LIMIT - 80).trimEnd();
    rest = kept + '\n\n✂️ обрезано ' + (rest.length - kept.length) +
           ' символов: лимит поста Mattermost.';
  }
  chunks.push(rest);
  return chunks;
}

// Нумерация обязательна: без неё несколько постов подряд читаются как
// несколько разных ответов на одно обращение.
function mmSplit(text) {
  const chunks = mmChunks(text);
  if (chunks.length < 2) return chunks;
  return chunks.map((c, i) => '**(' + (i + 1) + '/' + chunks.length + ')**\n' + c);
}

// Нода mattermost отправляет по посту на входной элемент, поэтому разбивка
// возвращается элементами, а порядок сохраняется исполнением по элементам.
const mmItems = (text) => mmSplit(text).map((t) => ({ json: { text: t } }));

// РАЗНЫЕ БЛОКИ — РАЗНЫМИ ПОСТАМИ.
//
// Сообщение заказчику и ТЗ для аналитика адресованы разным людям, и джун
// пересылает первое, не трогая второе. Пока они ехали одним постом, переслать
// было нечего: ни целиком, ни куском. Отдельный пост копируется целиком
// и кнопкой «Copy Text», а заголовок остаётся первой строкой — его джун
// снимает одним движением, в отличие от чересполосицы бизнеса и техники.
//
// Общий предохранитель на число постов свой: посекционного мало, три секции
// по четыре части — это двенадцать сообщений подряд в канале джуна.
const MM_MAX_POSTS = 6;

function mmSections(sections) {
  const items = [];
  let dropped = 0;
  for (const s of sections) {
    const body = String(s.body ?? '').trim();
    if (!body) continue;
    const chunks = mmChunks(body);
    chunks.forEach((c, i) => {
      const title = String(s.title ?? '').trim();
      const mark = chunks.length > 1 ? ' (' + (i + 1) + '/' + chunks.length + ')' : '';
      const head = title ? '**' + title + mark + '**\n' : (mark ? '**' + mark.trim() + '**\n' : '');
      if (items.length < MM_MAX_POSTS) items.push({ json: { text: head + c } });
      else dropped++;
    });
  }
  // Молча потерянный хвост — тот же тихий отказ: по виду канала ответ полный.
  if (dropped && items.length) {
    items[items.length - 1].json.text +=
      '\n\n✂️ не отправлено частей: ' + dropped + ' (предел ' + MM_MAX_POSTS +
      ' сообщений на одно обращение).';
  }
  return items.length ? items : [{ json: { text: '_ответ пустой_' } }];
}

// Ответ в личку. Служебного здесь нет: человек, который пишет боту, не правит
// базу знаний и не проверяет черновик — ему нужен ответ и честная оценка,
// насколько ему можно верить.
function dmReplyBody(a) {
  const parts = [a.draft || 'Не удалось собрать ответ.'];

  if (a.confidence_key === 'medium') {
    parts.push('');
    // Причина — НАСТОЯЩАЯ, а не одна на все случаи.
    //
    // Раньше здесь стояло «определение ещё не подтверждено» жёстко в коде: это
    // формулировка правила про status: draft, и она печаталась на любой средней
    // уверенности. Живой прогон 2026-08-27: ни одна прочитанная статья
    // черновиком не была, средняя стояла из-за неизвестного признака групп
    // доступа — а человек читал придуманное объяснение. Это подрывает ровно тот
    // сигнал, ради которого уверенность и считается: если причина неверна, её
    // перестают читать вместе со всей строкой.
    //
    // Понизил код — причина у нас есть и она точная. Заявила средней сама
    // модель — причины у нас нет, и выдумывать её нельзя: говорим только то,
    // что знаем. Блок gaps сюда не идёт, он про пробелы базы и адресован джуну,
    // а не человеку в личке.
    parts.push('⚠️ Уверенность средняя' +
      (a.confidence_capped && a.confidence_capped_reason
        ? ': ' + a.confidence_capped_reason + '.'
        : ' — ответ собран не полностью, перепроверьте перед использованием.'));
  } else if (a.confidence_key === 'none') {
    parts.push('');
    parts.push('⚠️ Ответа в базе знаний нет — лучше уточнить у команды HR-аналитики.');
  }
  return parts.join('\n');
}

const a = $('Call core').first().json;
return mmSections([{ title: '', body: dmReplyBody(a) }]);
